#!/usr/bin/env python3
"""Loopback Telnet echo fixture: generated bytes only, no shell, credentials or files."""
from socketserver import BaseRequestHandler, ThreadingTCPServer

IAC, WILL, WONT, DO, DONT, SB, SE = 255, 251, 252, 253, 254, 250, 240
READY = b"OH-Hatoba Telnet fixture ready\r\n"


class Handler(BaseRequestHandler):
    def handle(self):
        # Own echo and binary mode keep the client from locally echoing or rewriting input.
        offers = bytes([IAC, WILL, 1, IAC, WILL, 3, IAC, WILL, 0,
                        IAC, DO, 0, IAC, DO, 31])
        self.request.settimeout(30)
        self.request.sendall(offers + READY)
        state, option_command = "data", None
        try:
            while chunk := self.request.recv(65536):
                output = bytearray()
                for value in chunk:
                    if state == "data":
                        if value == IAC:
                            state = "iac"
                        else:
                            output.append(value)
                    elif state == "iac":
                        if value == IAC:
                            output.extend([IAC, IAC])
                            state = "data"
                        elif value in (WILL, WONT, DO, DONT):
                            option_command, state = value, "option"
                        elif value == SB:
                            state = "sub"
                        else:
                            state = "data"
                    elif state == "option":
                        # The preamble already offered the supported options. Acknowledge
                        # nothing twice; refuse any other option without an infinite loop.
                        if option_command == WILL and value not in (0, 31):
                            output.extend([IAC, DONT, value])
                        elif option_command == DO and value not in (0, 1, 3):
                            output.extend([IAC, WONT, value])
                        state = "data"
                    elif state == "sub":
                        if value == IAC:
                            state = "sub_iac"
                    elif state == "sub_iac":
                        state = "data" if value == SE else "sub"
                if output:
                    self.request.sendall(output)
        except (ConnectionError, TimeoutError):
            pass


class Server(ThreadingTCPServer):
    allow_reuse_address = True
    daemon_threads = True


if __name__ == "__main__":
    with Server(("127.0.0.1", 22323), Handler) as server:
        print("Disposable generated-data Telnet fixture ready on 22323", flush=True)
        server.serve_forever()
